INSERT INTO site_settings (id,site_name,tagline,hero_title,hero_subtitle,hero_video_url,hero_poster_url,primary_color,currency) VALUES (1,'Aroma & Grano','Un momento para disfrutar','Tu pausa favorita comienza aquí','Café de especialidad, postres artesanales y un rincón para compartir.','/assets/cafeteria.mp4','https://images.pexels.com/photos/302899/pexels-photo-302899.jpeg?auto=compress&cs=tinysrgb&w=1600','#c58c5b','Bs') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO about (id,title,history,mission,address,city,phone,email,hours,map_url) VALUES (1,'Nuestra historia','Aroma & Grano es una cafetería de ejemplo inspirada en el placer de reunir personas alrededor de una buena taza de café. Sustituye este texto por la historia real de tu negocio.','Preparar bebidas con cuidado y hacer de cada visita un buen recuerdo.','Dirección pendiente de confirmar','Cochabamba, Bolivia','Teléfono pendiente','contacto@ejemplo.com','Lunes a sábado · 08:00–20:00','') ON DUPLICATE KEY UPDATE id=id;
